class Solution:
    def minSpaceWastedKResizing(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        for i, x in enumerate(nums):
            pre[i + 1] = pre[i] + x

        @cache
        def dp(i, r):
            if i == n:
                return 0
            if r == 0:
                mx = max(nums[i:])
                return mx * (n - i) - (pre[n] - pre[i])
            best = float('inf')
            mx = 0
            for j in range(i, n):
                mx = max(mx, nums[j])
                cost = mx * (j - i + 1) - (pre[j + 1] - pre[i])
                best = min(best, cost + dp(j + 1, r - 1))
            return best

        return dp(0, k)

