class Solution {
public:
    int minSpaceWastedKResizing(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; ++i) pre[i + 1] = pre[i] + nums[i];
        vector<vector<long long>> memo(n, vector<long long>(k + 1, -1));
        function<long long(int, int)> dp = [&](int i, int r) -> long long {
            if (i == n) return 0;
            if (memo[i][r] != -1) return memo[i][r];
            if (r == 0) {
                long long mx = *max_element(nums.begin() + i, nums.end());
                return memo[i][r] = mx * (n - i) - (pre[n] - pre[i]);
            }
            long long best = LLONG_MAX, mx = 0;
            for (int j = i; j < n; ++j) {
                mx = max(mx, (long long) nums[j]);
                long long cost = mx * (j - i + 1) - (pre[j + 1] - pre[i]);
                best = min(best, cost + dp(j + 1, r - 1));
            }
            return memo[i][r] = best;
        };
        return (int) dp(0, k);
    }
};

