class Solution {
    private int n;
    private int[] nums;
    private long[] pre;
    private Long[][] memo;

    public int minSpaceWastedKResizing(int[] nums, int k) {
        n = nums.length;
        this.nums = nums;
        pre = new long[n + 1];
        for (int i = 0; i < n; ++i) pre[i + 1] = pre[i] + nums[i];
        memo = new Long[n][k + 1];
        return (int) dp(0, k);
    }

    private long dp(int i, int r) {
        if (i == n) return 0;
        if (memo[i][r] != null) return memo[i][r];
        if (r == 0) {
            long mx = 0;
            for (int j = i; j < n; ++j) mx = Math.max(mx, nums[j]);
            return memo[i][r] = mx * (n - i) - (pre[n] - pre[i]);
        }
        long best = Long.MAX_VALUE, mx = 0;
        for (int j = i; j < n; ++j) {
            mx = Math.max(mx, nums[j]);
            long cost = mx * (j - i + 1) - (pre[j + 1] - pre[i]);
            best = Math.min(best, cost + dp(j + 1, r - 1));
        }
        return memo[i][r] = best;
    }
}

