        for i in range(1, n + 1):
            g[1][i] = max(nums[:i]) * i - pre[i]
        for s in range(2, k + 2):
            for i in range(s, n + 1):
                mx = 0
                for p in range(i - 1, s - 2, -1):
                    mx = max(mx, nums[p])
                    cand = g[s - 1][p] + mx * (i - p) - (pre[i] - pre[p])
                    if cand < g[s][i]:
                        g[s][i] = cand
        return g[k + 1][n]

