class Solution {
public:
    int minSpaceWastedKResizing(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; ++i) pre[i + 1] = pre[i] + nums[i];
        const long long INF = LLONG_MAX / 4;
        vector<vector<long long>> g(k + 2, vector<long long>(n + 1, INF));
        for (int i = 1; i <= n; ++i)
            g[1][i] = (long long) *max_element(nums.begin(), nums.begin() + i) * i - pre[i];
        for (int s = 2; s <= k + 1; ++s) {
            for (int i = s; i <= n; ++i) {
                long long mx = 0, best = INF;
                for (int p = i - 1; p >= s - 1; --p) {
                    mx = max(mx, (long long) nums[p]);
                    best = min(best, g[s - 1][p] + mx * (i - p) - (pre[i] - pre[p]));
                }
                g[s][i] = best;
            }
        }
        return (int) g[k + 1][n];
    }
};

